  CHECK(!memcmp(&original,&proj,sizeof original));CHECK(!memcmp(&before,r,sizeof before));
  memset(proj.arr.lane,0,sizeof proj.arr.lane);seq.rec_refused=0;
  seq_rec_bass(&seq,0,52,100,1,0,0);
